const { api, action, params } = $input.first().json;

const apiConfigs = {
  ga4: {
    base_url: 'https://analyticsdata.googleapis.com/v1beta',
    endpoints: {
      reports: { method: 'POST', path: `/properties/${params.property_id || '{property_id}'}:runReport`, body: { dateRanges: [{ startDate: params.start_date || '7daysAgo', endDate: params.end_date || 'today' }], metrics: (params.metrics || 'sessions,totalUsers,screenPageViews').split(',').map(m => ({ name: m.trim() })), dimensions: (params.dimensions || 'date').split(',').map(d => ({ name: d.trim() })), limit: params.limit || 1000 } },
      realtime: { method: 'POST', path: `/properties/${params.property_id || '{property_id}'}:runRealtimeReport`, body: { metrics: [{ name: 'activeUsers' }, { name: 'screenPageViews' }], dimensions: [{ name: 'unifiedScreenName' }], limit: params.limit || 100 } },
      performance: { method: 'POST', path: `/properties/${params.property_id || '{property_id}'}:runReport`, body: { dateRanges: [{ startDate: params.start_date || '30daysAgo', endDate: params.end_date || 'today' }], metrics: [{ name: 'sessions' }, { name: 'totalUsers' }, { name: 'bounceRate' }, { name: 'averageSessionDuration' }, { name: 'conversions' }], dimensions: [{ name: 'sessionSource' }, { name: 'sessionMedium' }], limit: params.limit || 100 } }
    }
  },
  semrush: {
    base_url: 'https://api.semrush.com',
    endpoints: {
      domain_overview: { method: 'GET', path: `/?type=domain_ranks&key=${params.api_key || ''}&domain=${params.domain || ''}&database=${params.database || 'us'}&export_columns=Dn,Rk,Or,Ot,Oc,Ad,At,Ac`, query: {} },
      domain_organic: { method: 'GET', path: `/?type=domain_organic&key=${params.api_key || ''}&display_limit=${params.limit || 100}&domain=${params.domain || ''}&database=${params.database || 'us'}&export_columns=Ph,Po,Nq,Cp,Co,Kd,Ur,Tr,Tc,In`, query: {} },
      keyword_overview: { method: 'GET', path: `/?type=phrase_all&key=${params.api_key || ''}&phrase=${encodeURIComponent(params.keyword || '')}&database=${params.database || 'us'}&export_columns=Ph,Nq,Cp,Co,Kd,In`, query: {} },
      keyword_difficulty: { method: 'GET', path: `/?type=phrase_kdi&key=${params.api_key || ''}&phrase=${encodeURIComponent(params.keyword || '')}&database=${params.database || 'us'}&export_columns=Ph,Kd`, query: {} },
      keyword_gap: { method: 'GET', path: `/?type=domain_domains&key=${params.api_key || ''}&display_limit=${params.limit || 50}&domains=${(params.domains || []).join('|')}&database=${params.database || 'us'}&export_columns=Ph,P0,P1,P2,P3,P4,Nr,Td,In`, query: {} },
      competitors_organic: { method: 'GET', path: `/?type=domain_organic_organic&key=${params.api_key || ''}&display_limit=${params.limit || 10}&domain=${params.domain || ''}&database=${params.database || 'us'}&export_columns=Dn,Cr,Np,Or,Ot,Oc,Ad`, query: {} },
      backlinks_overview: { method: 'GET', path: `/?type=backlinks_overview&key=${params.api_key || ''}&target=${params.domain || ''}&export_columns=total,domains_num,urls_num,ips_num,follows_num,nofollows_num`, query: {} }
    }
  },
  search_console: {
    base_url: 'https://searchconsole.googleapis.com/v1',
    endpoints: {
      reports: { method: 'POST', path: `/sites/${encodeURIComponent(params.site_url || '{site_url}')}/searchAnalytics/query`, body: { startDate: params.start_date || new Date(Date.now() - 28 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], endDate: params.end_date || new Date().toISOString().split('T')[0], dimensions: (params.dimensions || 'query,page').split(',').map(d => d.trim()), rowLimit: params.limit || 1000 } },
      performance: { method: 'POST', path: `/sites/${encodeURIComponent(params.site_url || '{site_url}')}/searchAnalytics/query`, body: { startDate: params.start_date || new Date(Date.now() - 28 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], endDate: params.end_date || new Date().toISOString().split('T')[0], dimensions: ['query', 'page', 'country', 'device'], rowLimit: params.limit || 1000, type: params.search_type || 'web' } },
      sitemaps: { method: 'GET', path: `/sites/${encodeURIComponent(params.site_url || '{site_url}')}/sitemaps`, query: {} }
    }
  }
};

const config = apiConfigs[api];
if (!config) {
  return [{ json: { error: true, message: `Unknown analytics API: ${api}. Available: ${Object.keys(apiConfigs).join(', ')}` } }];
}

const endpoint = config.endpoints[action];
if (!endpoint) {
  return [{ json: { error: true, message: `Unknown action '${action}' for ${api}. Available: ${Object.keys(config.endpoints).join(', ')}` } }];
}

return [{
  json: {
    method: endpoint.method,
    url: config.base_url + endpoint.path,
    query: endpoint.query || {},
    body: endpoint.body || {},
    api: api,
    action: action
  }
}];

const input = $input.first().json;
const request = $('Build API Request').first().json;

if (input.error || input.statusCode >= 400) {
  return [{
    json: {
      error: true,
      api: request.api,
      action: request.action,
      status_code: input.statusCode || 500,
      message: input.message || input.error || 'API call failed',
      raw_error: input
    }
  }];
}

return [{
  json: {
    success: true,
    api: request.api,
    action: request.action,
    data: input.data || input.body || input,
    metadata: {
      timestamp: new Date().toISOString(),
      execution_id: $execution.id
    }
  }
}];
